'use client';

// Speaking Alita's replies. Server-side voices (Edge, ElevenLabs, OpenAI) are
// generated by the backend and played through one shared <audio> element;
// the "browser" provider uses the device's Web Speech API instead. Small
// external stores keep every speaker button, the auto-speak toggle and
// settings in sync.

import { useEffect, useSyncExternalStore } from 'react';
import * as api from './api';
import type { VoiceStatus } from './types';

export type PlayState = 'idle' | 'loading' | 'playing';

function store<T>(initial: T) {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next: T) => {
      value = next;
      listeners.forEach((l) => l());
    },
    subscribe: (l: () => void) => {
      listeners.add(l);
      return () => listeners.delete(l);
    },
  };
}

// ─── Playback ──────────────────────────────────────────────────────

const IDLE = { key: null as string | null, state: 'idle' as PlayState };
const playback = store(IDLE);
let audio: HTMLAudioElement | null = null;
let token = 0;

function release() {
  if (!audio) return;
  audio.onplaying = audio.onended = audio.onerror = null;
  audio.pause();
  audio.removeAttribute('src');
  audio.load();
  audio = null;
}

function stopBrowserSpeech() {
  try {
    window.speechSynthesis?.cancel();
  } catch {
    /* unsupported */
  }
}

export function stopSpeaking() {
  token++;
  release();
  stopBrowserSpeech();
  playback.set(IDLE);
}

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

/** Speak with the device voices (the "browser" provider). */
function speakLocally(key: string, text: string, status: VoiceStatus, fail: (m: string) => void) {
  const synth = typeof window !== 'undefined' ? window.speechSynthesis : undefined;
  if (!synth || typeof SpeechSynthesisUtterance === 'undefined') {
    fail('This browser has no speech synthesis. Choose a server voice instead.');
    return;
  }
  const mine = token;
  const utter = new SpeechSynthesisUtterance(text);
  const wanted = status.voice?.voice_id;
  const voices = synth.getVoices();
  const chosen =
    (wanted && voices.find((v) => v.name === wanted)) ||
    voices.find((v) => v.lang?.toLowerCase().startsWith('en-gb')) ||
    voices.find((v) => v.lang?.toLowerCase().startsWith('en')) ||
    voices[0];
  if (chosen) utter.voice = chosen;
  utter.rate = clamp(status.settings?.speed ?? 1, 0.5, 2);
  utter.onstart = () => mine === token && playback.set({ key, state: 'playing' });
  utter.onend = () => mine === token && playback.set(IDLE);
  utter.onerror = (e) => {
    if (mine !== token) return;
    playback.set(IDLE);
    if (e.error !== 'interrupted' && e.error !== 'canceled') fail(`Speech failed: ${e.error || 'unknown error'}`);
  };
  synth.cancel();
  synth.speak(utter);
}

/** Speak `text` for the message identified by `key`. Errors go to `onError`. */
export async function speak(key: string, text: string, onError?: (message: string) => void) {
  stopSpeaking();
  const mine = ++token;
  playback.set({ key, state: 'loading' });
  const fail = (message: string) => {
    if (mine !== token) return;
    release();
    stopBrowserSpeech();
    playback.set(IDLE);
    onError?.(message);
  };

  const status = playbackStatus();
  if (status?.provider === 'browser') {
    speakLocally(key, text, status, fail);
    return;
  }

  try {
    const prepared = await api.prepareSpeech(text);
    if (mine !== token) return;
    const el = new Audio(api.withToken(prepared.url));
    audio = el;
    el.onplaying = () => mine === token && playback.set({ key, state: 'playing' });
    el.onended = () => {
      if (mine !== token) return;
      release();
      playback.set(IDLE);
    };
    el.onerror = async () => {
      const state = await api.getSpeechState(prepared.id).catch(() => null);
      fail(state?.error || 'Could not play the audio.');
    };
    await el.play();
  } catch (e) {
    if (e instanceof DOMException && e.name === 'NotAllowedError') {
      fail('The browser blocked autoplay. Click the speaker button to listen.');
    } else if (e instanceof DOMException && e.name === 'AbortError') {
      // Replaced by another reply or stopped.
    } else {
      fail(api.errorMessage(e));
    }
  }
}

export function usePlayback(key: string): PlayState {
  const snap = useSyncExternalStore(playback.subscribe, playback.get, () => IDLE);
  return snap.key === key ? snap.state : 'idle';
}

/** Current shared playback state (for hands-free conversation turn-taking). */
export function getPlaybackState() {
  return playback.get();
}

export function subscribePlayback(listener: () => void) {
  return playback.subscribe(listener);
}

// ─── Voice status (which provider/voice?) ──────────────────────────

const status = store<VoiceStatus | null>(null);
let loading: Promise<void> | null = null;

function playbackStatus(): VoiceStatus | null {
  return status.get();
}

export function refreshVoiceStatus(): Promise<void> {
  loading = api
    .getVoiceStatus()
    .then((s) => status.set(s))
    .catch(() => undefined)
    .finally(() => {
      loading = null;
    });
  return loading;
}

export function useVoiceStatus(): VoiceStatus | null {
  const value = useSyncExternalStore(status.subscribe, status.get, () => null);
  useEffect(() => {
    if (status.get() === null && !loading) void refreshVoiceStatus();
  }, []);
  return value;
}

/** Device voices (for the "browser" provider), kept in sync with the browser. */
export function browserVoices(): SpeechSynthesisVoice[] {
  if (typeof window === 'undefined' || !window.speechSynthesis) return [];
  return window.speechSynthesis.getVoices();
}

export function useBrowserVoices(): SpeechSynthesisVoice[] {
  const listing = store<SpeechSynthesisVoice[]>([]);
  useEffect(() => {
    if (typeof window === 'undefined' || !window.speechSynthesis) return;
    const update = () => listing.set(browserVoices());
    update();
    window.speechSynthesis.addEventListener?.('voiceschanged', update);
    return () => window.speechSynthesis.removeEventListener?.('voiceschanged', update);
  }, []);
  return useSyncExternalStore(listing.subscribe, listing.get, () => []);
}

// ─── Auto-speak preference (per browser) ───────────────────────────

const AUTO_KEY = 'alita:auto-speak';
const autoSpeak = store(false);
let autoLoaded = false;

function loadAuto() {
  if (autoLoaded || typeof window === 'undefined') return;
  autoLoaded = true;
  try {
    autoSpeak.set(window.localStorage.getItem(AUTO_KEY) === '1');
  } catch {
    /* storage unavailable */
  }
}

export function setAutoSpeak(on: boolean) {
  autoSpeak.set(on);
  if (!on) stopSpeaking();
  try {
    window.localStorage.setItem(AUTO_KEY, on ? '1' : '0');
  } catch {
    /* storage unavailable */
  }
}

export function useAutoSpeak(): boolean {
  const value = useSyncExternalStore(autoSpeak.subscribe, autoSpeak.get, () => false);
  useEffect(loadAuto, []);
  return value;
}

/** Called when a reply finishes streaming in this tab. */
export function maybeAutoSpeak(key: string, text: string, onError?: (message: string) => void) {
  loadAuto();
  const s = status.get();
  if (!autoSpeak.get() || !text.trim() || !s?.configured || !s.voice) return;
  void speak(key, text, onError);
}
